import{_ as o,o as t,c as e,a5 as n}from"./chunks/framework.Cooo9kuv.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"604-根据表单批量生成docx文档-word文档批量生成","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["WORD批处理"],"标签":["批量生成word","生成docx文档"]},"headers":[],"relativePath":"md/WORD批处理/604-根据表单批量生成docx文档-word文档批量生成.md","filePath":"md/WORD批处理/604-根据表单批量生成docx文档-word文档批量生成.md"}'),p={name:"md/WORD批处理/604-根据表单批量生成docx文档-word文档批量生成.md"};function r(l,a,c,s,d,h){return t(),e("div",null,[...a[0]||(a[0]=[n('<h3 id="程序介绍" tabindex="-1">程序介绍 <a class="header-anchor" href="#程序介绍" aria-label="Permalink to &quot;程序介绍&quot;">​</a></h3><p>根据docx（word）模板批量生成不同内容的docx文档，可以批量插入数据、文本、图片并且保持原占位符格式不变。</p><p>**支持的文档格式：**docx文档格式</p><h3 id="程序初始截图展示" tabindex="-1">程序初始截图展示 <a class="header-anchor" href="#程序初始截图展示" aria-label="Permalink to &quot;程序初始截图展示&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505102629174641198968104.png" alt=""></p><h3 id="程序运行演示截图" tabindex="-1">程序运行演示截图 <a class="header-anchor" href="#程序运行演示截图" aria-label="Permalink to &quot;程序运行演示截图&quot;">​</a></h3><p>该部分截图为导入excell文档到程序后的结果，可以在excell中编辑后导入到程序，也可以在程序中编辑一部分后导出，然后再导出的excell中进行编辑然后导入到程序中。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505103140174641230034152.jpg" alt=""></p><h3 id="详细使用说明" tabindex="-1">详细使用说明 <a class="header-anchor" href="#详细使用说明" aria-label="Permalink to &quot;详细使用说明&quot;">​</a></h3><p>1、首先需要准备一个word文档模板，如下图所示</p><p>按照正常排版预留图片位置或文本本位置，调整列宽或行高，也可以不使用表格形式，指定占位符，如下图所示的** [这样形式的占位符]**，可以自行指定。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505103553174641255387445.png" alt=""></p><p>模板文档中的文本占位符要与程序中指定的一致，程序中双击单元格即可修改</p><blockquote><p>A列为生成的docx文档名称，可以自行修改，A1为标题行，无需做改动</p></blockquote><blockquote><p>B1 C1 D1 .....为docx文档中的占位符，如上图所示，可自行指定任意形式，只要不与文档内容中存在重复情况即可。</p></blockquote><p>2、选择选项则实现不同的效果，具体如下图所示</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505104010174641281017605.jpg" alt=""></p><p>3、docx模板和表格数据（也可以是excell文档）准备好后，进行生成操作</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505104259174641297988022.jpg" alt=""></p><p>生成两个文档，1和2文档</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505104315174641299511226.png" alt=""></p><h3 id="文档1内容" tabindex="-1">文档1内容 <a class="header-anchor" href="#文档1内容" aria-label="Permalink to &quot;文档1内容&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505104351174641303156624.png" alt=""></p><h3 id="文档2内容" tabindex="-1">文档2内容 <a class="header-anchor" href="#文档2内容" aria-label="Permalink to &quot;文档2内容&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505104422174641306274680.png" alt=""></p><h3 id="添加图片说明" tabindex="-1">添加图片说明 <a class="header-anchor" href="#添加图片说明" aria-label="Permalink to &quot;添加图片说明&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505104515174641311519762.png" alt=""></p><p>指定图片占位符后，在图片列单元格中拖入图片即可，拖入图片后仅显示图片名称，双击单元格可以看到完整图片路径。</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250505105916174641395654694.png" alt=""></p><p>如上图所示，程序中提供了演示使用的docx文档模板，及excell数据文档</p><h3 id="程序适用环境" tabindex="-1">程序适用环境 <a class="header-anchor" href="#程序适用环境" aria-label="Permalink to &quot;程序适用环境&quot;">​</a></h3><p>win7及以上64位操作系统</p><h3 id="程序下载" tabindex="-1">程序下载 <a class="header-anchor" href="#程序下载" aria-label="Permalink to &quot;程序下载&quot;">​</a></h3><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1805.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1805.html</a></p>',36)])])}const g=o(p,[["render",r]]);export{w as __pageData,g as default};
